CREATE TABLE workspaces(id TEXT PRIMARY KEY, initialized INTEGER NOT NULL DEFAULT 0 CHECK(initialized IN (0,1)), revision INTEGER NOT NULL DEFAULT 0, pantry_version INTEGER NOT NULL DEFAULT 0);
INSERT INTO workspaces(id) VALUES ('local');
CREATE TABLE ingredients(id TEXT PRIMARY KEY, name TEXT NOT NULL, singular TEXT NOT NULL);
CREATE TABLE ingredient_units(ingredient_id TEXT NOT NULL REFERENCES ingredients(id), unit TEXT NOT NULL CHECK(unit IN ('piece','g','ml')), PRIMARY KEY(ingredient_id,unit));
CREATE TABLE recipes(id TEXT PRIMARY KEY, metadata TEXT NOT NULL CHECK(json_valid(metadata)));
CREATE TABLE recipe_steps(recipe_id TEXT NOT NULL REFERENCES recipes(id), position INTEGER NOT NULL, text TEXT NOT NULL, PRIMARY KEY(recipe_id,position));
CREATE TABLE recipe_requirements(recipe_id TEXT NOT NULL REFERENCES recipes(id), ingredient_id TEXT NOT NULL, quantity_minor INTEGER NOT NULL CHECK(quantity_minor BETWEEN 0 AND 100000000 AND typeof(quantity_minor)='integer'), unit TEXT NOT NULL, position INTEGER NOT NULL, PRIMARY KEY(recipe_id,ingredient_id), UNIQUE(recipe_id,position), FOREIGN KEY(ingredient_id,unit) REFERENCES ingredient_units(ingredient_id,unit), CHECK(unit!='piece' OR quantity_minor%100=0));
CREATE TABLE pantry_items(workspace_id TEXT NOT NULL REFERENCES workspaces(id), ingredient_id TEXT NOT NULL, quantity_minor INTEGER NOT NULL CHECK(quantity_minor BETWEEN 0 AND 100000000 AND typeof(quantity_minor)='integer'), unit TEXT NOT NULL, PRIMARY KEY(workspace_id,ingredient_id), FOREIGN KEY(ingredient_id,unit) REFERENCES ingredient_units(ingredient_id,unit), CHECK(unit!='piece' OR quantity_minor%100=0));
CREATE TABLE shopping_lists(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id), recipe_id TEXT NOT NULL REFERENCES recipes(id), status TEXT NOT NULL CHECK(status IN ('ready','needsShopping','checkUnits')), pantry_version INTEGER NOT NULL, catalog_version TEXT NOT NULL);
CREATE TABLE shopping_list_items(workspace_id TEXT NOT NULL REFERENCES shopping_lists(workspace_id) ON DELETE CASCADE, ingredient_id TEXT NOT NULL, quantity_minor INTEGER NOT NULL CHECK(quantity_minor>0 AND quantity_minor<=100000000 AND typeof(quantity_minor)='integer'), unit TEXT NOT NULL, position INTEGER NOT NULL, PRIMARY KEY(workspace_id,ingredient_id), FOREIGN KEY(ingredient_id,unit) REFERENCES ingredient_units(ingredient_id,unit), CHECK(unit!='piece' OR quantity_minor%100=0));
CREATE TABLE catalog_metadata(id INTEGER PRIMARY KEY CHECK(id=1), version TEXT NOT NULL);
